#include "CloseToHSL/Core/Virtualization/Compatibility/Generated/VmcsProjection/YAKSys_Hybrid_CPU.Core.VmcsFieldAliasProjection.h"
#include <cassert>
using namespace YAKSys_Hybrid_CPU::Core;
int main(){ VmcsFieldAliasProjection p; auto policy=std::make_shared<EvidencePolicyDescriptor>(true,true,true); auto r=std::make_shared<VmcsFieldAliasRequest>(); r->Field=static_cast<VmcsField>(6); assert(p.ValidateAccess(r,policy)->Decision==VmcsFieldAliasDecision::UndefinedField); r->Field=VmcsField::GuestPc; assert(p.ValidateAccess(r,policy)->Decision==VmcsFieldAliasDecision::MissingGeneratedAlias); r->GeneratedAliasDeclared=true; assert(p.ValidateAccess(r,policy)->Decision==VmcsFieldAliasDecision::DescriptorValidationDenied); r->DescriptorValidated=true; assert(p.ValidateAccess(r,policy)->IsAllowed); r->EvidenceClass=EvidenceVisibilityClass::HostOwnedRuntimeEvidence; assert(p.ValidateAccess(r,policy)->Decision==VmcsFieldAliasDecision::HostOwnedEvidenceDenied); r->EvidenceClass=EvidenceVisibilityClass::CompatibilityAlias; r->Access=VmcsFieldAliasAccess::Write; r->AllowWrite=true; assert(p.ValidateAccess(r,policy)->Decision==VmcsFieldAliasDecision::WriteDenied); }
